import{_ as t,o,c as a,a2 as s}from"./chunks/framework.eFe5Lsvn.js";const l="/Mayhem/img/fuel-sim.jpg",m=JSON.parse('{"title":"Fuel sim","description":"","frontmatter":{},"headers":[],"relativePath":"app/fuel-sim.md","filePath":"app/fuel-sim.md"}'),i={name:"app/fuel-sim.md"};function r(n,e,h,d,u,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="fuel-sim" tabindex="-1">Fuel sim <a class="header-anchor" href="#fuel-sim" aria-label="Permalink to &quot;Fuel sim&quot;">​</a></h1><p><strong>Fuel sim</strong> in the toolbar simulates the FUEL on the field during playback. Robots push it around, and an extended intake takes it in only as fast as its intake rate. Everything else it touches gets shoved, the way a real intake bulldozes part of a pile.</p><p><img src="'+l+'" alt="The Fuel sim panel"></p><p>The timeline shows how much fuel we&#39;re holding and keeps running after the robots stop until the pushed fuel has rolled to rest.</p><h2 id="our-robot" tabindex="-1">Our robot <a class="header-anchor" href="#our-robot" aria-label="Permalink to &quot;Our robot&quot;">​</a></h2><p>Our robot uses its solved path and its <strong>Intake extended</strong> spans. Set its <em>intake rate</em> (fuel per second) and <em>capacity</em> (0 = no limit) in the Fuel sim panel. An out-of-date path doesn&#39;t take part until you generate it again.</p><h2 id="other-robots" tabindex="-1">Other robots <a class="header-anchor" href="#other-robots" aria-label="Permalink to &quot;Other robots&quot;">​</a></h2><p>Add allies and opponents from the panel. Each drives a smooth curve through its points at a set max speed and acceleration, facing along the curve, with its intake out at the front.</p><ul><li>Click its path to select it, then drag its points to reshape the path or drag the robot itself to move the whole path.</li><li>Double-click the field to add a point at the end, <kbd>⇧</kbd>-click a point to remove it, and press <kbd>Delete</kbd> to remove the robot.</li><li>The copy button mirrors it to the other alliance.</li></ul><h2 id="what-blocks-fuel" tabindex="-1">What blocks fuel <a class="header-anchor" href="#what-blocks-fuel" aria-label="Permalink to &quot;What blocks fuel&quot;">​</a></h2><p>Fuel bounces off the field walls and, by default, off the obstacles paths avoid (the hubs, trench walls and towers). To change that for one obstacle, select it in <strong>Field</strong> mode and set <strong>Fuel sim</strong> to <em>Blocks fuel</em> or <em>Fuel passes through</em>.</p><p>The 2026 preset&#39;s bumps are disabled for paths (robots drive over them) but block fuel. With the fuel sim on, obstacles that only block fuel are outlined in amber.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li>The other robots and intake settings are saved in the project file. They never make a path out of date, and the solver ignores them.</li><li>It&#39;s a 2D, top-down model. Fuel doesn&#39;t stack or fly, and robots don&#39;t collide with each other.</li><li>The FUEL properties come from FIRST and AndyMark&#39;s 2026 Scoring Element Testing Report (215 g, 5.91 in). Rolling friction and bounce values are estimates.</li></ul>',14)])])}const f=t(i,[["render",r]]);export{m as __pageData,f as default};
